// This file implements Phase 2 (Workflow loading) of the implementation plan in
// docs/website/content/docs/architecture/bench-workflow-engine.md: parsing the
// Workflow/Step YAML shape from the doc's "Primitives" section into the
// api/tooling/workflow/v1 generated types, and validating the result.
//
// Deliberately does NOT yaml.Unmarshal directly into *workflowv1.Workflow: two of
// its fields resist reflection-based YAML decoding even though they carry plain
// `yaml:"..."` struct tags (auto-generated by protoc-gen-gotag, with no custom
// unmarshal logic behind them):
//
//   - Step.With / Step.Expect are *structpb.Struct (google.protobuf.Struct) —
//     internally a `Fields map[string]*Value` where Value wraps a oneof interface.
//     yaml.v3's reflection-based decoder has no way to construct that shape from a
//     YAML mapping node.
//   - Step.OnFailure is FailurePolicy, an int32-backed enum type. A YAML scalar like
//     `on_failure: continue` has no matching case for a plain int32 field.
//
// The fix is the same "boundary" discipline model.go already uses for bun/jsonb, one
// layer earlier: yaml.Unmarshal into a plain-Go-typed intermediate struct that
// mirrors the YAML shape (yamlWorkflowDoc et al., below), then convert that into
// *workflowv1.Workflow/*workflowv1.Step by hand — map[string]interface{} ->
// structpb.NewStruct for with/expect, and a small string->enum lookup (the same
// pattern model.go already uses for RunStatus/StepStatus) for on_failure.
package main

import (
	"fmt"
	"os"
	"strings"

	workflowv1 "github.com/steady-bytes/draft/api/tooling/workflow/v1"

	"google.golang.org/protobuf/types/known/structpb"
	"gopkg.in/yaml.v3"
)

// --- Intermediate YAML shape -------------------------------------------------
//
// Mirrors the schema in the doc's "Primitives" section field-for-field. Note this
// isn't a 1:1 mirror of the generated proto messages: the YAML nests name/description
// under `metadata:` and a webhook's signature config under `webhook.signature:`,
// while the proto flattens both (Workflow.name/description directly, and
// WebhookTrigger.signature_header/secret_ref directly) — the conversion functions
// below account for that difference. `apiVersion`/`kind` are parsed but not
// otherwise used; Bench only has one kind of document today.

type yamlWorkflowDoc struct {
	APIVersion string       `yaml:"apiVersion"`
	Kind       string       `yaml:"kind"`
	Metadata   yamlMetadata `yaml:"metadata"`
	Trigger    yamlTrigger  `yaml:"trigger"`
	Steps      []yamlStep   `yaml:"steps"`
}

type yamlMetadata struct {
	Name        string `yaml:"name"`
	Description string `yaml:"description"`
}

type yamlTrigger struct {
	Webhook *yamlWebhookTrigger `yaml:"webhook"`
}

type yamlWebhookTrigger struct {
	Slug      string         `yaml:"slug"`
	Signature *yamlSignature `yaml:"signature"`
}

type yamlSignature struct {
	Header    string `yaml:"header"`
	SecretRef string `yaml:"secret_ref"`
}

type yamlStep struct {
	Name string `yaml:"name"`
	Uses string `yaml:"uses"`
	// With/Expect parse naturally into map[string]interface{} — yaml.v3 (unlike
	// yaml.v2) decodes mapping nodes assigned to an interface{}-shaped target as
	// map[string]interface{}, which is exactly the shape structpb.NewStruct expects.
	With      map[string]interface{} `yaml:"with"`
	Expect    map[string]interface{} `yaml:"expect"`
	DependsOn []string               `yaml:"depends_on"`
	OnFailure string                 `yaml:"on_failure"`
	Retry     *yamlRetryPolicy       `yaml:"retry"`
}

type yamlRetryPolicy struct {
	Attempts int32  `yaml:"attempts"`
	Backoff  string `yaml:"backoff"`
}

// --- Loading ------------------------------------------------------------------

// LoadWorkflowFile reads a workflow YAML file from disk, parses it, converts it to
// the wire type, and validates it. It does not execute anything.
func LoadWorkflowFile(path string) (*workflowv1.Workflow, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read workflow file %q: %w", path, err)
	}
	w, err := ParseWorkflow(data)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return w, nil
}

// ParseWorkflow parses workflow YAML bytes, converts them to a *workflowv1.Workflow,
// and validates the result. Returns the first validation error found.
func ParseWorkflow(data []byte) (*workflowv1.Workflow, error) {
	var doc yamlWorkflowDoc
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return nil, fmt.Errorf("failed to parse workflow yaml: %w", err)
	}

	w, err := doc.toProto()
	if err != nil {
		return nil, err
	}

	if err := Validate(w); err != nil {
		return nil, err
	}
	return w, nil
}

// --- YAML -> proto conversion ---------------------------------------------------

func (doc *yamlWorkflowDoc) toProto() (*workflowv1.Workflow, error) {
	w := &workflowv1.Workflow{
		Name:        doc.Metadata.Name,
		Description: doc.Metadata.Description,
	}

	if doc.Trigger.Webhook != nil {
		webhook := &workflowv1.WebhookTrigger{
			Slug: doc.Trigger.Webhook.Slug,
		}
		if doc.Trigger.Webhook.Signature != nil {
			webhook.SignatureHeader = doc.Trigger.Webhook.Signature.Header
			webhook.SecretRef = doc.Trigger.Webhook.Signature.SecretRef
		}
		w.Trigger = &workflowv1.Trigger{Webhook: webhook}
	}

	steps := make([]*workflowv1.Step, 0, len(doc.Steps))
	for _, ys := range doc.Steps {
		step, err := ys.toProto()
		if err != nil {
			return nil, err
		}
		steps = append(steps, step)
	}
	w.Steps = steps

	return w, nil
}

func (ys *yamlStep) toProto() (*workflowv1.Step, error) {
	step := &workflowv1.Step{
		Name:      ys.Name,
		Uses:      ys.Uses,
		DependsOn: ys.DependsOn,
	}

	if ys.With != nil {
		with, err := structpb.NewStruct(ys.With)
		if err != nil {
			return nil, fmt.Errorf("step %q: with: %w", ys.Name, err)
		}
		step.With = with
	}
	if ys.Expect != nil {
		expect, err := structpb.NewStruct(ys.Expect)
		if err != nil {
			return nil, fmt.Errorf("step %q: expect: %w", ys.Name, err)
		}
		step.Expect = expect
	}

	// A missing on_failure defaults to FAILURE_POLICY_FAIL: "a step's failure fails
	// the run by default" per the doc's Execution model section, and matches
	// FailurePolicy's own zero value being FAILURE_POLICY_UNSPECIFIED rather than a
	// usable default.
	onFailure := workflowv1.FailurePolicy_FAILURE_POLICY_FAIL
	if ys.OnFailure != "" {
		key := "FAILURE_POLICY_" + strings.ToUpper(ys.OnFailure)
		v, ok := workflowv1.FailurePolicy_value[key]
		if !ok {
			return nil, fmt.Errorf("step %q: invalid on_failure %q", ys.Name, ys.OnFailure)
		}
		onFailure = workflowv1.FailurePolicy(v)
	}
	step.OnFailure = onFailure

	if ys.Retry != nil {
		step.Retry = &workflowv1.RetryPolicy{
			Attempts: ys.Retry.Attempts,
			Backoff:  ys.Retry.Backoff,
		}
	}

	return step, nil
}

// --- Validation -----------------------------------------------------------------

// Validate checks a converted workflow against the load-time rules described in the
// doc's Phase 2 deliverable: required fields, a uses: scheme of bench:// or
// garage://, no dangling depends_on references, and no cycle in the *effective*
// depends_on graph (after applying the "defaults to the previous step" rule). Returns
// the first problem found, with enough detail to act on (the offending step/value),
// rather than a generic "invalid workflow" error.
func Validate(w *workflowv1.Workflow) error {
	if strings.TrimSpace(w.GetName()) == "" {
		return fmt.Errorf("workflow name is required")
	}
	if len(w.GetSteps()) == 0 {
		return fmt.Errorf("workflow %q: at least one step is required", w.GetName())
	}

	stepNames := make(map[string]bool, len(w.GetSteps()))
	for i, s := range w.GetSteps() {
		if strings.TrimSpace(s.GetName()) == "" {
			return fmt.Errorf("workflow %q: step %d: name is required", w.GetName(), i+1)
		}
		if stepNames[s.GetName()] {
			return fmt.Errorf("workflow %q: duplicate step name %q", w.GetName(), s.GetName())
		}
		stepNames[s.GetName()] = true

		if strings.TrimSpace(s.GetUses()) == "" {
			return fmt.Errorf("step %q: uses is required", s.GetName())
		}
		scheme, _, hasScheme := strings.Cut(s.GetUses(), "://")
		if !hasScheme || (scheme != "bench" && scheme != "garage") {
			return fmt.Errorf("step %q: uses %q must have scheme bench:// or garage://", s.GetName(), s.GetUses())
		}
	}

	// Dangling depends_on references: checked against the literal (not
	// default-applied) depends_on list, since a defaulted entry always points at the
	// previous step, which is declared by construction.
	for _, s := range w.GetSteps() {
		for _, dep := range s.GetDependsOn() {
			if !stepNames[dep] {
				return fmt.Errorf("step %q depends_on undeclared step %q", s.GetName(), dep)
			}
		}
	}

	if err := checkAcyclic(w.GetSteps()); err != nil {
		return err
	}

	return nil
}

// effectiveDependsOn applies the "empty depends_on defaults to the previous step in
// declaration order" rule (doc's Primitives section, and Step.depends_on's own field
// comment in service.proto) to build the graph that actually needs to run acyclic —
// not just the literal YAML.
func effectiveDependsOn(steps []*workflowv1.Step) map[string][]string {
	graph := make(map[string][]string, len(steps))
	for i, s := range steps {
		deps := s.GetDependsOn()
		if len(deps) == 0 && i > 0 {
			deps = []string{steps[i-1].GetName()}
		}
		graph[s.GetName()] = deps
	}
	return graph
}

// stepColor tracks DFS state for cycle detection: unvisited, in-progress (on the
// current recursion stack), and fully explored.
type stepColor int

const (
	stepUnvisited stepColor = iota
	stepInProgress
	stepDone
)

// checkAcyclic runs a standard DFS-with-recursion-stack cycle check over the
// effective depends_on graph. On finding a back edge (an in-progress node reached
// again), it reports the cycle as the recursion-stack path from that node's first
// occurrence back to itself, e.g. "create-course -> query-course -> create-course".
func checkAcyclic(steps []*workflowv1.Step) error {
	graph := effectiveDependsOn(steps)
	color := make(map[string]stepColor, len(steps))
	var stack []string

	var visit func(name string) error
	visit = func(name string) error {
		switch color[name] {
		case stepInProgress:
			start := 0
			for i, n := range stack {
				if n == name {
					start = i
					break
				}
			}
			cycle := append(append([]string{}, stack[start:]...), name)
			return fmt.Errorf("cycle detected: %s", strings.Join(cycle, " -> "))
		case stepDone:
			return nil
		}

		color[name] = stepInProgress
		stack = append(stack, name)
		for _, dep := range graph[name] {
			if err := visit(dep); err != nil {
				return err
			}
		}
		stack = stack[:len(stack)-1]
		color[name] = stepDone
		return nil
	}

	for _, s := range steps {
		if color[s.GetName()] == stepUnvisited {
			if err := visit(s.GetName()); err != nil {
				return err
			}
		}
	}
	return nil
}
